--liquibase formatted sql
--changeset venomenon328:033-availability-novelty-final-review splitStatements:false
-- Issue #189. Authoritative source: docs/analysis/availability-novelty-final-review-v1-20260907.tsv
-- Review AVAILABILITY_NOVELTY_V1_20260907, catalog f8855121af336a7c13cd799cafede5f9b9420f28.
-- All APPROVED_FINAL origins have equal authority. No base_draw_weight changes approved.
-- Expected hashes protect the preceding code-based concept aggregates, including all metadata,
-- G/T levels and graph; IDs, timestamps and optimistic versions are intentionally excluded.
-- Other participants and historical snapshots are outside the migration's write scope.

LOCK TABLE ingredient_concept, ingredient_refinement, ingredient_functional_role,
    ingredient_culinary_flag, ingredient_culinary_dimension, ingredient_culinary_country,
    ingredient_seasonality, ingredient_availability, participant,
    functional_role, culinary_flag, culinary_dimension IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMP TABLE availability_novelty_review (
    code text PRIMARY KEY,
    review_version text NOT NULL CHECK (review_version = 'AVAILABILITY_NOVELTY_V1_20260907'),
    applicable boolean NOT NULL,
    expected_fingerprint text NOT NULL,
    novelty_level smallint,
    georgia_level text,
    tobias_level text,
    georgia_note text,
    tobias_note text,
    CHECK (CASE WHEN applicable THEN
        novelty_level IS NOT NULL AND novelty_level BETWEEN 1 AND 5
        AND georgia_level IS NOT NULL AND georgia_level IN ('EASY','PLANNED','SPECIALTY','DIFFICULT','UNAVAILABLE')
        AND tobias_level IS NOT NULL AND tobias_level IN ('EASY','PLANNED','SPECIALTY','DIFFICULT','UNAVAILABLE')
        AND georgia_note IS NOT NULL AND georgia_note ~ '[^[:space:]]'
        AND tobias_note IS NOT NULL AND tobias_note ~ '[^[:space:]]'
    ELSE novelty_level IS NULL AND georgia_level IS NULL AND tobias_level IS NULL
        AND georgia_note IS NULL AND tobias_note IS NULL END)
) ON COMMIT DROP;


DO $guard$
DECLARE mismatches text;
BEGIN
    IF (SELECT count(*) FROM availability_novelty_review) <> 860
        OR (SELECT count(*) FROM availability_novelty_review WHERE applicable) <> 853
        OR (SELECT count(*) FROM availability_novelty_review WHERE NOT applicable) <> 7 THEN
        RAISE EXCEPTION 'Issue #189: invalid review manifest cardinality (expected 860 / 853 / 7)';
    END IF;
    SELECT string_agg(coalesce(ic.code, r.code), ', ' ORDER BY coalesce(ic.code, r.code) COLLATE "C")
    INTO mismatches FROM ingredient_concept ic FULL JOIN availability_novelty_review r USING (code)
    WHERE ic.code IS NULL OR r.code IS NULL;
    IF mismatches IS NOT NULL THEN
        RAISE EXCEPTION 'Issue #189: missing, renamed or new catalog codes: %', mismatches;
    END IF;
    IF (SELECT count(*) FROM participant WHERE code IN ('GEORGIA','TOBIAS')) <> 2 THEN
        RAISE EXCEPTION 'Issue #189: expected participants GEORGIA and TOBIAS are missing';
    END IF;
    SELECT string_agg(code, ', ' ORDER BY code COLLATE "C") INTO mismatches
    FROM (
select ic.code, jsonb_build_object(
        'concept', to_jsonb(ic) - ARRAY['id','created_at','updated_at','version'],
        'roles', (select coalesce(jsonb_agg(v order by v::text collate "C"), '[]'::jsonb) from (select ref.code as v from ingredient_functional_role rel join functional_role ref on ref.id = rel.functional_role_id where rel.ingredient_concept_id = ic.id) values_by_code),
        'flags', (select coalesce(jsonb_agg(v order by v::text collate "C"), '[]'::jsonb) from (select ref.code as v from ingredient_culinary_flag rel join culinary_flag ref on ref.id = rel.culinary_flag_id where rel.ingredient_concept_id = ic.id) values_by_code),
        'dimensions', (select coalesce(jsonb_agg(v order by v::text collate "C"), '[]'::jsonb) from (select jsonb_build_array(ref.code, rel.level) as v from ingredient_culinary_dimension rel join culinary_dimension ref on ref.id = rel.culinary_dimension_id where rel.ingredient_concept_id = ic.id) values_by_code),
        'countries', (select coalesce(jsonb_agg(v order by v::text collate "C"), '[]'::jsonb) from (select rel.country_code as v from ingredient_culinary_country rel  where rel.ingredient_concept_id = ic.id) values_by_code),
        'seasonality', (select coalesce(jsonb_agg(v order by v::text collate "C"), '[]'::jsonb) from (select jsonb_build_array(rel.month, rel.weight_multiplier) as v from ingredient_seasonality rel  where rel.ingredient_concept_id = ic.id) values_by_code),
        'availability', (select coalesce(jsonb_agg(v order by v::text collate "C"), '[]'::jsonb) from (select jsonb_build_array(ref.code, rel.availability_level) as v from ingredient_availability rel join participant ref on ref.id = rel.participant_id and ref.code in ('GEORGIA','TOBIAS') where rel.ingredient_concept_id = ic.id) values_by_code),
        'parents', (select coalesce(jsonb_agg(parent.code order by parent.code collate "C"), '[]'::jsonb) from ingredient_refinement rel join ingredient_concept parent on parent.id = rel.parent_concept_id where rel.child_concept_id = ic.id)
    ) as state from ingredient_concept ic
    ) catalog_state JOIN availability_novelty_review r USING (code)
    WHERE encode(sha256(convert_to(state::text, 'UTF8')), 'hex') <> r.expected_fingerprint;
    IF mismatches IS NOT NULL THEN
        RAISE EXCEPTION 'Issue #189: unreviewed catalog changes for codes: %. Reconcile affected deltas before migration.', mismatches;
    END IF;
    IF EXISTS (SELECT 1 FROM ingredient_availability a JOIN participant p ON p.id = a.participant_id
               WHERE p.code IN ('GEORGIA','TOBIAS') AND a.curator_note IS NOT NULL) THEN
        RAISE EXCEPTION 'Issue #189: unexpected pre-existing G/T availability notes';
    END IF;
    IF EXISTS (SELECT 1 FROM ingredient_concept ic JOIN availability_novelty_review r USING (code)
               WHERE NOT r.applicable AND ic.active AND ic.random_draw_enabled) THEN
        RAISE EXCEPTION 'Issue #189: a reviewed structure node unexpectedly belongs to the active random pool';
    END IF;
END $guard$;

-- Every G/T aggregate changes through a note/level upsert or N/A cleanup.
-- Advance the aggregate version to invalidate any editor opened before this migration.
UPDATE ingredient_concept ic
SET novelty_level = r.novelty_level, version = ic.version + 1
FROM availability_novelty_review r WHERE ic.code = r.code;

DELETE FROM ingredient_availability a
USING ingredient_concept ic, participant p, availability_novelty_review r
WHERE a.ingredient_concept_id = ic.id AND a.participant_id = p.id
    AND ic.code = r.code AND NOT r.applicable AND p.code IN ('GEORGIA','TOBIAS');

SELECT ic.id, p.id, v.level, v.note
FROM availability_novelty_review r JOIN ingredient_concept ic ON ic.code = r.code
CROSS JOIN LATERAL (VALUES ('GEORGIA', r.georgia_level, r.georgia_note),
                           ('TOBIAS', r.tobias_level, r.tobias_note)) v(code, level, note)
JOIN participant p ON p.code = v.code
WHERE r.applicable
ON CONFLICT (ingredient_concept_id, participant_id) DO UPDATE
SET availability_level = excluded.availability_level, curator_note = excluded.curator_note;
